// HandleKey handles the stats-specific keys; q/tab/shift+tab fall through to Root.
// While the content table holds keyboard focus (a click put it there) the keys it
// binds go to it first — Textual's focused-widget-first binding order, with its
// SkipAction fall-through (datatable.HandlesKey) — and Tab/Shift+Tab leave it by
// stats_app.py _cycle_focus's rule (below).
func (m *model) HandleKey(msg tea.KeyPressMsg) (tea.Cmd, bool) {
	if m.tableFocused() {
		if m.contentTable.HandlesKey(msg) {
			var cmd tea.Cmd
			*m.contentTable, cmd = m.contentTable.Update(msg)
			return cmd, true
		}
		switch msg.String() {
		case "tab", "shift+tab":
			// _cycle_focus: the table is not in the panel cycle, so its index is -1
			// and the target is cycle[(-1 ± 1) % n] — Tab → the first panel (the
			// session panel in multi-session), Shift+Tab → n-2 (the sidebar, in
			// either mode).
			step := 1
			if msg.String() == "shift+tab" {
				step = -1
			}
			n := len(m.panels)
			return m.focusRegion(((-1+step)%n + n) % n), true
		}
	}
	switch msg.String() {
	case "up", "down", "enter":
		// Forward to the focused list: up/down move its cursor (emit Highlighted);
		// enter emits Selected (→ the layout list applies a preset). handled=true
		// stops Root routing these to no-op member cycling.
		reg := m.rm.Active()
		if reg == nil { // no active region yet (before Init's focus)
			return nil, true
		}
		if lv, ok := reg.Group.Focused().(*listview.Model); ok {
			var cmd tea.Cmd
			*lv, cmd = lv.Update(msg)
			if msg.String() == "enter" && m.sessionIdx >= 0 && lv == m.panels[m.sessionIdx].list {
				if it, ok := lv.Highlighted(); ok {
					m.sessionPick = it.Meta // the Selected this Enter emits
				}
			}
			// Highlight-to-preview happens IN this Update for the sidebar, so the
			// first frame after the key is already final (sidebar cursor and content
			// agree). Waiting for the HighlightedMsg would render an intermediate
			// frame (new cursor, old pane) whose leftover cell attributes made the
			// parity capture timing-dependent. The later HighlightedMsg is a no-op.
			if lv == m.panels[m.sidebarIdx].list {
				if it, ok := lv.Highlighted(); ok && it.Meta != m.currentPane {
					cmd = tea.Batch(cmd, m.showPane(it.Meta))
				}
			}
			return cmd, true
		}
		return nil, true
	case "s":
		if m.sessionIdx >= 0 {
			return m.focusRegion(m.sessionIdx), true
		}
		return nil, true // no-op in single-session mode
	case "c":
		return m.focusRegion(m.layoutIdx), true
	case "left":
		return m.leftRight(-1), true
	case "right":
		return m.leftRight(+1), true
	case "[":
		return m.bracket(-1), true
	case "]":
		return m.bracket(+1), true
	case "r":
		return tea.Batch(m.refresh(), m.root.Notify("Refreshed", toast.WithTimeout(time.Second))), true
	case "n", "d", "e":
		// The custom-layout actions only act while the layout list is focused
		// (stats_app.action_new_custom / _edit_custom / _delete_custom).
		if m.rm.ActiveIndex() != m.layoutIdx {
			return nil, true
		}
		switch msg.String() {
		case "n":
			return m.newCustomFlow(), true
		case "e":
			return m.editCustom(), true
		default:
			return m.deleteCustom(), true
		}
	}
	return nil, false
}

