// HandleModal receives ALL input while a modal is up — keys via app.Root's focus
// trap, mouse and any other input message (paste, textinput's async clipboard
// result) via the host's Update — so the base screen sees nothing.
func (m *model) HandleModal(msg tea.Msg) tea.Cmd {
	switch mod := m.modal.(type) {
	case *nameInputModal:
		return m.handleNameModal(mod, msg)
	case *paneSelectorModal:
		return m.handlePaneModal(mod, msg)
	}
	return nil
}

// handleNameModal: Esc/Cancel → nil; Enter on the input or OK → the trimmed name
// (or nil); Tab cycles input → OK → Cancel; everything else on the input is text
// entry (so q/n/e type rather than act). Buttons answer Enter only (Textual's
// Button binds enter, not space). In the too-small state only Esc works.
func (m *model) handleNameModal(mod *nameInputModal, msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		k := msg.String()
		if k == "esc" {
			return m.dismiss(nil)
		}
		if mod.tooSmall() {
			return nil
		}
		switch k {
		case "tab":
			return mod.fg.Next()
		case "shift+tab":
			return mod.fg.Prev()
		}
		switch mod.fg.Focused() {
		case mod.inp:
			if k == "enter" {
				return m.dismiss(mod.value())
			}
			var cmd tea.Cmd
			*mod.inp, cmd = mod.inp.Update(msg)
			return cmd
		case mod.ok:
			if k == "enter" {
				return m.dismiss(mod.value())
			}
		case mod.cancel:
			if k == "enter" {
				return m.dismiss(nil)
			}
		}
		return nil

	case tea.PasteMsg:
		// A terminal paste goes to the focused widget (Textual Paste event): only the
		// input accepts it.
		if !mod.tooSmall() && mod.fg.Focused() == mod.inp {
			var cmd tea.Cmd
			*mod.inp, cmd = mod.inp.Update(msg)
			return cmd
		}
		return nil

	case tea.MouseMotionMsg:
		mod.ok.SetHovered(mod.ok.hit(m.zm, zModalOK, msg))
		mod.cancel.SetHovered(mod.cancel.hit(m.zm, zModalCancel, msg))
		return nil

	case tea.MouseClickMsg:
		if msg.Mouse().Button != tea.MouseLeft || mod.tooSmall() {
			return nil
		}
		switch {
		case m.zm.Get(zModalInput).InBounds(msg):
			return mod.fg.FocusByZone(zModalInput)
		case mod.ok.hit(m.zm, zModalOK, msg):
			return m.dismiss(mod.value())
		case mod.cancel.hit(m.zm, zModalCancel, msg):
			return m.dismiss(nil)
		}
		return nil

	case tea.MouseReleaseMsg, tea.MouseWheelMsg, input.InputChangedMsg, input.InputSubmittedMsg:
		// Enter is handled as a key above, so the input's own Submitted message is
		// ignored (no double dismiss).
		return nil

	default:
		// textinput's internal messages (the async ctrl+v clipboard paste result,
		// cursor messages) arrive here; the input ignores anything it does not know.
		if mod.tooSmall() {
			return nil
		}
		var cmd tea.Cmd
		*mod.inp, cmd = mod.inp.Update(msg)
		return cmd
	}
}

// handlePaneModal: Esc/Cancel → nil; Enter (list or Save) and ctrl+s → the checked
// ids; space toggles; up/down/home/end/pgup/pgdn move (and scroll) the list; Tab
// cycles list → Save → Cancel. Enter on a focused Cancel CANCELS — a deliberate
// fix: the Python modal's screen-level on_key saves on any Enter, even with Cancel
// focused (recorded as an upstream defect). Mouse: hover/click/wheel/scrollbar on
// the list (a row click highlights + toggles), clicks on Save/Cancel. In the
// too-small state only Esc works — nothing is ever toggled invisibly.
func (m *model) handlePaneModal(mod *paneSelectorModal, msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case tea.KeyPressMsg:
		k := msg.String()
		if k == "esc" {
			return m.dismiss(nil)
		}
		if mod.tooSmall() {
			return nil
		}
		switch k {
		case "tab":
			return mod.fg.Next()
		case "shift+tab":
			return mod.fg.Prev()
		case "ctrl+s":
			return m.dismiss(mod.selectedIDs())
		case "enter":
			if mod.fg.Focused() == mod.cancel {
				return m.dismiss(nil)
			}
			return m.dismiss(mod.selectedIDs())
		}
		if mod.fg.Focused() == mod.list {
			var cmd tea.Cmd
			*mod.list, cmd = mod.list.Update(msg)
			return cmd
		}
		return nil

	case tea.MouseMotionMsg:
		mod.save.SetHovered(mod.save.hit(m.zm, zModalSave, msg))
		mod.cancel.SetHovered(mod.cancel.hit(m.zm, zModalCancel, msg))
		z := m.zm.Get(zModalList)
		if mod.list.Grabbing() {
			_, ly := z.LocalPos(msg) // unclamped: a drag may leave the zone
			mod.list.DragScrollbar(ly)
			mod.list.SetHovered(selectionlist.None)
			return nil
		}
		lx, ly := z.Pos(msg) // (-1,-1) outside → clears hover
		mod.list.SetScrollbarHovered(mod.list.ScrollbarAt(lx, ly))
		mod.list.SetHovered(mod.list.RowAt(lx, ly))
		return nil

	case tea.MouseClickMsg:
		if msg.Mouse().Button != tea.MouseLeft || mod.tooSmall() {
			return nil
		}
		switch {
		case mod.save.hit(m.zm, zModalSave, msg):
			return m.dismiss(mod.selectedIDs())
		case mod.cancel.hit(m.zm, zModalCancel, msg):
			return m.dismiss(nil)
		}
		z := m.zm.Get(zModalList)
		if !z.InBounds(msg) {
			return nil
		}
		focus := mod.fg.FocusByZone(zModalList)
		lx, ly := z.Pos(msg)
		if mod.list.ScrollbarAt(lx, ly) {
			mod.list.GrabScrollbar(ly)
			return focus
		}
		// RowAt is None on the border / a disabled header / the scrollbar gutter;
		// ToggleRow ignores None (memory zone-commit-guard-none-row).
		return tea.Batch(focus, mod.list.ToggleRow(mod.list.RowAt(lx, ly)))

	case tea.MouseReleaseMsg:
		mod.list.ReleaseScrollbar()
		return nil

	case tea.MouseWheelMsg:
		if m.zm.Get(zModalList).InBounds(msg) {
			mod.list.Wheel(msg.Mouse().Button == tea.MouseWheelUp)
		}
		return nil
	}
	// Paste and the list's own Highlighted/Toggled/Changed messages: nothing to do.
	return nil
}

// --- session / group cycling (session/ helpers, t13_2) ---

// cycleSession advances the ←/→ session ring: the cross-group ring plus the
// aggregate as its fixed FINAL stop (mirroring stats_app.py _session_ring /
// _cycle_session). Landing on the aggregate leaves the selected group unchanged.
func (m *model) cycleSession(step int) tea.Cmd {
	if !m.multi {
		return nil // single-session: ←/→ reserved for op-cycling (t13_4)
	}
	ring := append(
		session.CrossGroupRing(m.sessions),
		session.CrossGroupRingEntry{Session: allSessionsKey, Group: m.selectedGroup},
	)
	cur := m.current
	e := session.CrossGroupStep(ring, &cur, step)
	if e == nil {
		return nil
	}
	if e.Group != nil { // real session: sync the group axis; aggregate leaves it be
		m.selectedGroup = e.Group
	}
	return m.applySession(e.Session)
}

// cycleGroup advances the [/] project-group axis (stats_app.py _cycle_group). It
// never selects the aggregate; a nil result means <2 groups (no-op).
func (m *model) cycleGroup(step int) tea.Cmd {
	if !m.multi {
		return nil
	}
	sel := session.AdvanceGroupSelection(m.sessions, m.selectedGroup, m.current, step, ptr(allSessionsKey))
	if sel == nil {
		return nil // fewer than two groups
	}
	m.selectedGroup = sel.SelectedGroup
	m.sessionPick = "" // supersedes a pending list pick even without a re-point
	var cmd tea.Cmd
	if sel.RepointSession != nil {
		cmd = m.applySession(*sel.RepointSession)
	}
	group := session.UngroupedLabel
	if m.selectedGroup != nil && *m.selectedGroup != "" {
		group = *m.selectedGroup
	}
	return tea.Batch(cmd, m.root.Notify("Group: "+group, toast.WithTimeout(time.Second)))
}

// applySession switches the current session: updates the title, re-highlights the
// matching session-list row, re-renders the preview for the current pane, and
// toasts the new project (stats_app.py _apply_session_selection).
func (m *model) applySession(key string) tea.Cmd {
	m.current = key
	m.sessionPick = "" // a newer session choice supersedes a pending list pick
	m.root.SetTitle(m.titleText())
	if m.sessionIdx >= 0 {
		lv := m.panels[m.sessionIdx].list
		for i, it := range lv.Items() {
			if it.Meta == key {
				lv.SetIndex(i)
				break
			}
		}
	}
	cmd := m.showPane(m.currentPane) // re-render the same pane for the new session
	return tea.Batch(cmd, m.root.Notify("Project: "+sessionLabel(key), toast.WithTimeout(time.Second)))
}

// refresh re-renders the current preview (the seeded data is static, so this just
// mirrors stats_app.py's action_refresh without a live reload). Mirrors `r`.
func (m *model) refresh() tea.Cmd { return m.showPane(m.currentPane) }

// showPane sets the previewed pane (by id), resolves its title from the registry,
// and rebuilds the content table if the pane is a table pane. Every show is a
// FRESH pane, as in Textual (_show_pane remounts → a new _RankingPane with
// op_idx = win_idx = 0): the ranking op/window state resets on every re-show
// (highlight change, session apply, refresh, layout rebuild); only the
// ←/→ [ / ] cycles (which rebuild the table directly) keep it. The remount also
// removes a focused content table: Textual's Screen._reset_focus then focuses the
// previous widget in the focus chain — the layout list — and so does this
// (returning that focus command).
func (m *model) showPane(paneID string) tea.Cmd {
	wasFocused := m.tableFocused()
	m.blurTable()
	m.currentPane = paneID
	m.verifiedOpIdx, m.verifiedWinIdx = 0, 0
	m.usageOpIdx, m.usageWinIdx = 0, 0
	if def, ok := paneDefs[paneID]; ok {
		m.currentPaneTitle = def.title
	} else {
		m.currentPaneTitle = paneID
	}
	m.rebuildContentTable()
	m.syncContentScroll()
	if wasFocused {
		return m.focusRegion(m.layoutIdx)
	}
	return nil
}

// tableFocused reports whether the content table holds keyboard focus; the table's
// own focus flag is the single source of truth.
func (m *model) tableFocused() bool { return m.contentTable != nil && m.contentTable.Focused() }

// focusTable gives the content table keyboard focus (Textual focuses a DataTable
// on any mouse-down inside it): no left region stays active, so every list renders
// blurred and no .focused_panel gutter shows (stats_app.py _apply_focus_hint marks
// only a focused panel list).
func (m *model) focusTable() {
	m.rm.Deactivate()
	m.contentTable.Focus()
}

// blurTable drops the content table's keyboard focus (no-op without a table).
func (m *model) blurTable() {
	if m.contentTable != nil {
		m.contentTable.Blur()
	}
}

// focusRegion moves keyboard focus to left region i, taking it off the content
// table.
func (m *model) focusRegion(i int) tea.Cmd {
	m.blurTable()
	return m.rm.Activate(i)
}

// activateLayout makes name (a preset or custom layout) the active one, persists
// it, rebuilds the sidebar (highlight → first pane, hover cleared, first pane
// previewed) and the layout list (cursor on name). Keyboard focus stays on the
// layout region (the Enter came from there). Mirrors _activate_layout_item.
func (m *model) activateLayout(name string) {
	m.cfg.Active = name
	_ = m.cfg.saveBestEffort()
	m.rebuildSidebar()
	m.rebuildLayoutList(name)
}

// rebuildSidebar rebuilds the sidebar from the resolved active layout
// (_rebuild_sidebar): highlight the first pane and preview it, or show the empty
// state when the layout resolves to no known panes.
func (m *model) rebuildSidebar() {
	ids := m.cfg.resolveActiveLayout()
	sidebar := m.panels[m.sidebarIdx].list
	sidebar.SetItems(sidebarItemsFor(ids))
	sidebar.SetIndex(0)
	sidebar.SetHovered(listview.None)
	if len(ids) == 0 {
		m.showPane(noPanesID)
		return
	}
	m.showPane(ids[0])
}

// rebuildLayoutList refreshes the layout rows (the `● ` active marker moves, a
// custom appears/disappears) and puts the cursor on focus (_rebuild_layout_list).
func (m *model) rebuildLayoutList(focus string) {
	lv := m.panels[m.layoutIdx].list
	items := layoutItems(m.cfg)
	lv.SetItems(items)
	lv.SetHovered(listview.None)
	m.syncListHeights()
	for i, it := range items {
		if _, name := parseLayoutMeta(it.Meta); it.Meta != layoutMeta(layoutKindNew, "") && name == focus {
			lv.SetIndex(i)
			break
		}
	}
}

// highlightedLayout returns the layout list's highlighted row (kind, name).
func (m *model) highlightedLayout() (string, string) {
	it, ok := m.panels[m.layoutIdx].list.Highlighted()
	if !ok {
		return "", ""
	}
	return parseLayoutMeta(it.Meta)
}

// --- custom-layout flows (stats_app.py _new_custom_flow / action_edit_custom /
// action_delete_custom / _open_pane_selector) ---

// newCustomFlow opens the NameInput; its result continues in onName.
func (m *model) newCustomFlow() tea.Cmd {
	mod := newNameInputModal(newLayoutPrompt, m.cols, m.rows)
	return m.openModal(mod, func(v any) tea.Msg {
		if s, ok := v.(string); ok {
			return nameResultMsg{name: &s}
		}
		return nameResultMsg{}
	})
}

// onName continues the new-custom flow: an empty/cancelled name does nothing; a
// name already used by a custom or a preset is rejected with a warning toast;
// otherwise the PaneSelector opens empty.
func (m *model) onName(msg nameResultMsg) tea.Cmd {
	if msg.name == nil || *msg.name == "" {
		return nil
	}
	name := *msg.name
	if m.cfg.isCustom(name) || m.cfg.isPreset(name) {
		return m.root.Notify(fmt.Sprintf("Name '%s' is already taken", name), toast.WithSeverity(toast.Warning))
	}
	return m.openPaneSelector(name, nil, true)
}

// editCustom opens the PaneSelector pre-checked with the highlighted custom
// layout's panes (no-op on a preset / the "+ New custom" row).
func (m *model) editCustom() tea.Cmd {
	kind, name := m.highlightedLayout()
	if kind != layoutKindCustom {
		return nil
	}
	return m.openPaneSelector(name, m.cfg.customPanes(name), false)
}

// deleteCustom deletes the highlighted custom layout; deleting the active one
// falls back to the overview preset and rebuilds the sidebar. Presets are not
// deletable (a warning toast says so).
func (m *model) deleteCustom() tea.Cmd {
	kind, name := m.highlightedLayout()
	if kind != layoutKindCustom {
		return m.root.Notify("Only custom layouts can be deleted", toast.WithSeverity(toast.Warning))
	}
	if !m.cfg.deleteCustom(name) {
		return nil
	}
	if m.cfg.Active == name {
		m.cfg.Active = fallbackLayout
		m.rebuildSidebar()
	}
	_ = m.cfg.saveBestEffort()
	m.rebuildLayoutList(m.cfg.Active)
	return m.root.Notify(fmt.Sprintf("Deleted '%s'", name))
}

func (m *model) openPaneSelector(name string, initial []string, isNew bool) tea.Cmd {
	mod := newPaneSelectorModal(name, initial, m.cols, m.rows)
	return m.openModal(mod, func(v any) tea.Msg {
		ids, ok := v.([]string)
		if !ok {
			return panesResultMsg{name: name, isNew: isNew, cancelled: true}
		}
		return panesResultMsg{name: name, ids: ids, isNew: isNew}
	})
}

// onPanes finishes the flow: cancel does nothing (a cancelled new layout is
// discarded, with a toast); an empty selection is rejected with a warning;
// otherwise store the custom layout, make it active, persist, rebuild.
func (m *model) onPanes(msg panesResultMsg) tea.Cmd {
	if msg.cancelled {
		if msg.isNew {
			return m.root.Notify(fmt.Sprintf("Discarded new layout '%s'", msg.name), toast.WithTimeout(time.Second))
		}
		return nil
	}
	if len(msg.ids) == 0 {
		return m.root.Notify("Select at least one pane", toast.WithSeverity(toast.Warning))
	}
	m.cfg.setCustom(msg.name, msg.ids)
	m.activateLayout(msg.name)
	return m.root.Notify(fmt.Sprintf("Saved '%s'", msg.name))
}

// --- modal plumbing (app.Root funnel) ---

// openModal pushes a fresh modal through app.Root (focus trap + auto-focus) and
// arranges for its dismiss value to reach Update as toMsg(value).
func (m *model) openModal(mod statsModal, toMsg func(v any) tea.Msg) tea.Cmd {
	if m.root.ModalActive() {
		return nil // single-modal invariant: m.modal tracks the ONE open modal
	}
	m.modal = mod
	sh := m.sh
	return m.root.OpenModal(
		func() ui.Screen { return mod },
		func(v any) { sh.pending = append(sh.pending, toMsg(v)) },
	)
}

// dismiss pops the open modal (focus returns to the layout region) and handles
// its queued result IN THE SAME Update, on this live model. Handling it here —
// not via a later message — means no intermediate frame (the bare base screen
// between NameInput and PaneSelector, or the stale layout before a save lands)
// is ever rendered: a flicker for the user and a render-history-dependent cell
// encoding for the parity capture.
func (m *model) dismiss(v any) tea.Cmd {
	cmds := []tea.Cmd{m.root.DismissModal(v)}
	m.modal = nil
	pending := m.sh.pending
	m.sh.pending = nil
	for _, pm := range pending {
		cmds = append(cmds, m.handleResult(pm))
	}
	return tea.Batch(cmds...)
}

// handleResult continues a custom-layout flow from a modal's dismiss result.
func (m *model) handleResult(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case nameResultMsg:
		return m.onName(msg)
	case panesResultMsg:
		return m.onPanes(msg)
	}
	return nil
}

// leftRight routes ←/→: op-cycle on the ranking panes, else session-cycle
// (multi-session). bracket routes [/]: window-cycle on the ranking panes, else
// group-cycle. Mirrors the pane-guarded action routing in stats_app.py.
func (m *model) leftRight(step int) tea.Cmd {
	switch m.currentPane {
	case "agents.verified":
		m.cycleVerifiedOp(step)
		return nil
	case "agents.usage":
		m.cycleUsageOp(step)
		return nil
	}
	if m.multi {
		return m.cycleSession(step)
	}
	return nil
}

func (m *model) bracket(step int) tea.Cmd {
	switch m.currentPane {
	case "agents.verified":
		m.cycleVerifiedWindow(step)
		return nil
	case "agents.usage":
		m.cycleUsageWindow(step)
		return nil
	}
	if m.multi {
		return m.cycleGroup(step)
	}
	return nil
}

func (m *model) cycleVerifiedOp(step int) {
	if n := len(m.data.fx.Verified.Operations); n > 1 {
		m.verifiedOpIdx = (m.verifiedOpIdx + step + n) % n
		m.rebuildContentTable()
	}
}

func (m *model) cycleVerifiedWindow(step int) {
	n := len(cycleWindows)
	m.verifiedWinIdx = (m.verifiedWinIdx + step + n) % n
	m.rebuildContentTable()
}

func (m *model) cycleUsageOp(step int) {
	if n := len(m.data.fx.Usage.Operations); n > 1 {
		m.usageOpIdx = (m.usageOpIdx + step + n) % n
		m.rebuildContentTable()
	}
}

func (m *model) cycleUsageWindow(step int) {
	n := len(cycleWindows)
	m.usageWinIdx = (m.usageWinIdx + step + n) % n
	m.rebuildContentTable()
}

// rebuildContentTable (re)builds the persistent content table from the current
// pane + op/window/session state, at the current content-table size; nil for
// non-table panes (re-push on every visual change — memory
// embedded-scroll-widget-refresh-and-wheel). Op/window cycling keeps Textual's
// table (clear + re-populate), so a focused table stays focused across the rebuild,
// its cursor back on the first row as DataTable.clear leaves it.
func (m *model) rebuildContentTable() {
	if m.tableFocused() {
		defer func() {
			if m.contentTable != nil {
				m.contentTable.Focus()
			}
		}()
	}
	switch m.currentPane {
	case "agents.verified":
		t := buildVerifiedTable(m)
		m.contentTable = &t
	case "agents.usage":
		t := buildUsageTable(m)
		m.contentTable = &t
	case "labels.heatmap":
		t := buildHeatmapTable(m)
		m.contentTable = &t
	default:
		m.contentTable = nil
	}
}

// contentInner is the #content region's inner size (outer minus the padding 1 2).
func (m model) contentInner() (int, int) {
	bw, bh := m.root.BodySize()
	w := bw - leftColW - 4 // horizontal padding 2 each side
	h := bh - 2            // vertical padding 1 each side
	if w < 1 {
		w = 1
	}
	if h < 1 {
		h = 1
	}
	return w, h
}

// contentTableSize is the content DataTable's box size: the inner content area
// minus the pane's header block. Both build-time and the zone mark use it so the
// marked rect equals the table's own layout (RowAt/ScrollbarAt stay aligned).
func (m model) contentTableSize(headerLines int) (int, int) {
	w, h := m.contentInner()
	if h -= headerLines; h < 1 {
		h = 1
	}
	return w, h
}

// currentTableHeaderLines is the header block height for the active table pane
// (the ranking panes carry a header — wrapped at the inner width — plus a blank;
// the heatmap has none).
func (m model) currentTableHeaderLines() int {
	switch m.currentPane {
	case "agents.verified":
		op, window, total := m.verifiedState()
		return m.rankingHeaderLines(op, window, total)
	case "agents.usage":
		op, window, total := m.usageState()
		return m.rankingHeaderLines(op, window, total)
	}
	return 0
}

// renderPaneBody renders the current pane into an iw×ih inner area: the registry
// pane, the empty-layout state, or the unknown-pane placeholder.
func (m model) renderPaneBody(iw, ih int) string {
	if def, ok := paneDefs[m.currentPane]; ok {
		return def.render(&m, iw, ih)
	}
	surface := style.Active().Color(style.Surface)
	if m.currentPane == noPanesID {
		return lipgloss.NewStyle().Foreground(style.DimColor(surface, style.Active().Color(style.Text))).
			Background(surface).Render("No panes in this layout")
	}
	return "Pane unavailable"
}

// syncContentScroll (re)builds the content scroll viewport for the current pane at
// the current size — called on every visual change (pane/session/refresh/layout via
// showPane, and resize), so the viewport never shows stale content (memory
// embedded-scroll-widget-refresh-and-wheel). A pane that fits, a table pane, or an
// unknown size gets no viewport.
func (m *model) syncContentScroll() {
	if bw, _ := m.root.BodySize(); bw <= 0 || m.contentTable != nil {
		m.contentScroll, m.contentScrollPane = nil, ""
		return
	}
	iw, ih := m.contentInner()
	body := m.renderPaneBody(iw, ih)
	bw, bh := lipgloss.Width(body), lipgloss.Height(body)
	if bh > ih {
		// A vertical bar will show: Textual sizes a `1fr` child against the
		// scrollable region (the viewport minus that bar), so a width-fluid pane (the
		// summary row) lays out narrower. A fixed-width chart renders the same.
		body = m.renderPaneBody(max(1, iw-scrollbar.VThickness), ih)
		bw, bh = lipgloss.Width(body), lipgloss.Height(body)
	}
	if bw <= iw && bh <= ih {
		m.contentScroll, m.contentScrollPane = nil, ""
		return
	}
	// The viewport pads with unstyled cells, so fill on $surface the part of the
	// viewport beside the content on a non-overflowing axis (the container
	// background shows there in Textual). Sized so it never forces a second bar:
	// the padded extent stays within what the other bar leaves.
	padW, padH := bw, bh
	if bh > ih {
		padW = max(bw, iw-scrollbar.VThickness)
	}
	if bw > iw {
		padH = max(bh, ih-scrollbar.HThickness)
	}
	body = styled().Width(padW).Height(padH).Render(body)
	if m.contentScroll != nil && m.contentScrollPane == m.currentPane {
		// One update for content + size: the offset is clamped against the final
		// geometry only, never against an intermediate (new body, old size) state.
		m.contentScroll.SetContentSize(body, iw, ih)
		return
	}
	sc := scroll.New(scroll.WithSize(iw, ih), scroll.WithContent(body))
	m.contentScroll, m.contentScrollPane = &sc, m.currentPane
}

// sidebarItemsFor builds the sidebar rows for a resolved layout: pane ids → titles.
func sidebarItemsFor(ids []string) []listview.Item {
	items := make([]listview.Item, 0, len(ids))
	for _, id := range ids {
		if def, ok := paneDefs[id]; ok {
			items = append(items, listview.Item{Label: def.title, Meta: id})
		}
	}
	return items
}

func (m model) titleText() string {
	if m.multi {
		return "ait stats — " + sessionLabel(m.current)
	}
	return "ait stats"
}

// --- mouse (host-owned, zone-local against each list's body zone) ---

// grabbing reports whether any scrollbar (a panel list, the content table, or
// the open PaneSelector's list) is being dragged; a drag keeps following the
// pointer even over a toast.
func (m *model) grabbing() bool {
	for _, p := range m.panels {
		if p.list.Grabbing() {
			return true
		}
	}
	if m.contentTable != nil && m.contentTable.Grabbing() {
		return true
	}
	if m.contentScroll != nil && m.contentScroll.Grabbing() {
		return true
	}
	if ps, ok := m.modal.(*paneSelectorModal); ok && ps.list.Grabbing() {
		return true
	}
	return false
}

// handleMouse routes row hover / click / wheel / scrollbar against every panel's
// body zone, whose scanned rect starts at the list's first row so RowAt and
// ScrollbarAt coordinates are never offset by the panel title or the focus gutter.
// This copies demos/listview, extended with region focus + sidebar preview.
func (m *model) handleMouse(msg tea.Msg) tea.Cmd {
	switch msg := msg.(type) {
	case tea.MouseMotionMsg:
		for _, p := range m.panels {
			z := m.zm.Get(p.bodyID)
			if p.list.Grabbing() {
				_, ly := z.LocalPos(msg) // unclamped: a drag may leave the zone
				p.list.DragScrollbar(ly)
				p.list.SetHovered(listview.None)
				continue
			}
			lx, ly := z.Pos(msg) // (-1,-1) when outside → clears hover
			p.list.SetScrollbarHovered(p.list.ScrollbarAt(lx, ly))
			p.list.SetHovered(p.list.RowAt(lx, ly))
		}
		// Content DataTable hover/drag (host-owned, like the left panels).
		if m.contentTable != nil {
			z := m.zm.Get(contentTableZoneID)
			if m.contentTable.Grabbing() {
				lx, ly := z.LocalPos(msg)
				m.contentTable.DragScrollbar(lx, ly)
				m.contentTable.SetHovered(datatable.None)
			} else {
				lx, ly := z.Pos(msg)
				m.contentTable.SetScrollbarHovered(m.contentTable.ScrollbarAt(lx, ly))
				m.contentTable.HoverAt(lx, ly) // row, or single cell for the heatmap
			}
		}
		m.routeContentScroll(msg) // scrollbar hover / thumb drag
		return nil

	case tea.MouseClickMsg:
		if msg.Mouse().Button != tea.MouseLeft {
			return nil
		}
		for i, p := range m.panels {
			z := m.zm.Get(p.bodyID)
			if !z.InBounds(msg) {
				continue
			}
			lx, ly := z.Pos(msg)
			if p.list.ScrollbarAt(lx, ly) {
				// A ScrollBar is not focusable (Textual): the press only grabs it and
				// keyboard focus — a panel list or the content table — stays put.
				p.list.GrabScrollbar(ly)
				return nil
			}
			m.blurTable()
			cmd := m.rm.FocusRegionByZone(p.region.ID) // activate this panel
			row := p.list.RowAt(lx, ly)
			if items := p.list.Items(); i == m.sessionIdx && row >= 0 && row < len(items) {
				m.sessionPick = items[row].Meta // the Selected this click emits
			}
			return tea.Batch(cmd, p.list.Activate(row))
		}
		// Content DataTable click: a press on a scrollbar only grabs it — Textual's
		// ScrollBar is its own non-focusable widget, so focus stays where it was
		// (headless twin probe, t31/t36). Any other press inside the table (rows,
		// header, the empty area past the last column or row) takes keyboard focus,
		// as Textual focuses a DataTable on mouse-down, then does the row / cell
		// click action.
		if m.contentTable != nil {
			z := m.zm.Get(contentTableZoneID)
			if z.InBounds(msg) {
				lx, ly := z.Pos(msg)
				if m.contentTable.ScrollbarAt(lx, ly) != datatable.ScrollbarNone {
					m.contentTable.GrabScrollbar(lx, ly)
					return nil
				}
				m.focusTable()
				return m.contentTable.ActivateAt(lx, ly)
			}
		}
		// Content scroll viewport: a bar press grabs / jumps the track; a press on the
		// pane body does nothing. Neither moves keyboard focus.
		if m.zm.Get(contentScrollZoneID).InBounds(msg) {
			m.routeContentScroll(msg)
		}
		return nil

	case tea.MouseReleaseMsg:
		for _, p := range m.panels {
			p.list.ReleaseScrollbar()
		}
		if m.contentTable != nil {
			m.contentTable.ReleaseScrollbar()
		}
		m.routeContentScroll(msg)
		return nil

	case tea.MouseWheelMsg:
		up := msg.Mouse().Button == tea.MouseWheelUp
		for _, p := range m.panels {
			if m.zm.Get(p.bodyID).InBounds(msg) {
				p.list.Wheel(up)
			}
		}
		if m.contentTable != nil && m.zm.Get(contentTableZoneID).InBounds(msg) {
			m.contentTable.Wheel(msg.Mouse().Button)
		}
		if m.zm.Get(contentScrollZoneID).InBounds(msg) {
			m.routeContentScroll(msg)
		}
		return nil
	}
	return nil
}

// routeContentScroll hands a mouse event to the content scroll viewport, anchored
// at its scanned zone (scroll hit-tests in screen coordinates from its origin).
// Motion and release always go through — hover clears off the bars and a grab
// keeps dragging off the zone; callers gate presses and wheel on the zone. It
// never touches keyboard focus: neither a ScrollBar nor the non-focusable #content
// / chart Static takes focus on a mouse-down in Textual.
func (m *model) routeContentScroll(msg tea.Msg) {
	if m.contentScroll == nil {
		return
	}
	z := m.zm.Get(contentScrollZoneID)
	if z.IsZero() {
		return
	}
	m.contentScroll.SetOrigin(z.StartX, z.StartY)
	*m.contentScroll, _ = m.contentScroll.Update(msg)
}

// --- sizing / view ---

// Panel list caps (rows), mirroring the twin's CSS: #session_list max-height 6 /
// #session_panel max-height 40%, #layout_list max-height 10 / #layout_panel
// max-height 50% (percentages of the left column = the body height). Each panel
// adds 2 chrome rows (title + accent separator); leftColumnHeights allocates them.
const (
	sessionListMaxRows = 6
	sessionPanelMaxPct = 40
	layoutListMaxRows  = 10
	layoutPanelMaxPct  = 50
	panelChromeRows    = 2
)

// syncListHeights re-budgets the capped session/layout lists from the body height
// (on resize and whenever the layout rows change): each list gets the rows its
// panel has left after the chrome (leftColumnHeights), scrolling past that — so
// many custom layouts never push the frame past the terminal. A panel with no row
// left for its list hides it (renderPanel) but keeps a valid 1-row list, so its
// keys and highlight still work like Textual's clipped ListView. A no-op before
// the first resize (unknown size).
func (m *model) syncListHeights() {
	_, bodyH := m.root.BodySize()
	if bodyH <= 0 {
		return
	}
	session, sidebar, layout := m.leftColumnHeights(bodyH)
	if m.sessionIdx >= 0 {
		m.panels[m.sessionIdx].list.SetHeight(max(1, session-panelChromeRows))
	}
	m.panels[m.layoutIdx].list.SetHeight(max(1, layout-panelChromeRows))
	// The sidebar takes the rest (#sidebar height: 1fr) and scrolls within it.
	m.panels[m.sidebarIdx].list.SetHeight(sidebar)
}

// rowTenths is the fixed-point scale of leftColumnHeights: Textual keeps panel
// heights fractional, and 40% / 50% of an integer body are exact in tenths.
const rowTenths = 10

// leftColumnHeights reproduces Textual's vertical layout of #left_column: the rows
// of the session panel (0 when single-session), the sidebar and the layout panel.
// #session_panel / #layout_panel are height:auto (chrome + up to their list cap)
// with max-height 40% / 50% kept fractional, and never below their 1-row border
// gutter; the 1fr #sidebar gets H - int(s+l), or 1 when nothing remains
// (resolve_fraction_unit); VerticalLayout then places each child at
// floor(cumulative y) (textual/_resolve.py resolve_box_models,
// textual/layouts/vertical.py). The sum can exceed bodyH on tiny bodies; the
// column clip in renderLeftColumn drops the overflow, as Textual's does.
func (m model) leftColumnHeights(bodyH int) (session, sidebar, layout int) {
	s := 0
	if m.sessionIdx >= 0 {
		s = panelTenths(len(m.panels[m.sessionIdx].list.Items()), sessionListMaxRows, sessionPanelMaxPct, bodyH)
	}
	l := panelTenths(len(m.panels[m.layoutIdx].list.Items()), layoutListMaxRows, layoutPanelMaxPct, bodyH)
	sb := max(bodyH-(s+l)/rowTenths, 1) * rowTenths
	session = s / rowTenths
	sidebar = (s+sb)/rowTenths - session
	layout = (s+sb+l)/rowTenths - (s+sb)/rowTenths
	return session, sidebar, layout
}

// panelTenths is a capped panel's Textual height in tenths of a row: its auto
// height (chrome + up to listMax rows), capped at pct% of the body, never below
// the 1-row border gutter.
func panelTenths(items, listMax, pct, bodyH int) int {
	auto := (panelChromeRows + min(items, listMax)) * rowTenths
	return max(rowTenths, min(auto, pct*bodyH*rowTenths/100))
}

func (m model) View() tea.View {
	if m.root.ModalActive() && m.modal != nil {
		// Opaque full-screen modal (covers header + footer, like a pushed screen).
		return m.root.WrapView(m.modal.render(m.zm, m.cols, m.rows))
	}
	bodyW, bodyH := m.root.BodySize()
	left := m.renderLeftColumn(bodyH)
	content := m.renderContent(bodyW-leftColW, bodyH)
	body := lipgloss.JoinHorizontal(lipgloss.Top, left, content)
	return m.root.WrapView(m.root.Frame(body))
}

// renderLeftColumn stacks the (2 or 3) panels at their Textual heights.
func (m model) renderLeftColumn(bodyH int) string {
	session, sidebar, layout := m.leftColumnHeights(bodyH)
	parts := make([]string, 0, 3)
	for i, p := range m.panels {
		h := sidebar
		switch i {
		case m.sessionIdx:
			h = session
		case m.layoutIdx:
			h = layout
		}
		parts = append(parts, m.renderPanel(p, h))
	}
	col := lipgloss.JoinVertical(lipgloss.Left, parts...)
	// Pad the whole column to bodyH on $surface so any rounding gap carries the bg,
	// and clip it there: the frame never grows past the body (tiny terminals).
	return lipgloss.NewStyle().
		Background(style.Active().Color(style.Surface)).
		Width(leftColW).Height(bodyH).MaxHeight(bodyH).
		Render(col)
}

// renderPanel draws one panel h rows tall: optional accent separators + title, the
// zone-marked list body, then a left gutter carrying the .focused_panel border-left
// cue ($primary when the region has focus, else $surface = invisible, stable
// width). The separators are borders (Textual border-box): they always draw, and
// the title + list content is clipped to the rows left between them — a list with
// no row left is not drawn (nor zone-marked) at all.
func (m model) renderPanel(p *panel, h int) string {
	surface := style.Active().Color(style.Surface)
	accent := style.Active().Color(style.Accent)

	seps := 0
	if p.topSep {
		seps++
	}
	if p.botSep {
		seps++
	}
	contentH := h - seps
	content := make([]string, 0, 2)
	if p.title != "" {
		content = append(content, lipgloss.NewStyle().Bold(true).Foreground(accent).
			Background(surface).Width(innerW).Render(" "+p.title))
	}
	if contentH-len(content) >= 1 {
		content = append(content, m.zm.Mark(p.bodyID, p.list.Render()))
	}

	inner := make([]string, 0, 3)
	if p.topSep {
		inner = append(inner, lipgloss.NewStyle().Foreground(accent).Background(surface).
			Width(innerW).Render(repeat("▔", innerW)))
	}
	if contentH > 0 && len(content) > 0 {
		// Pad the content to its rows on $surface (sidebar 1fr fill) and clip it there.
		inner = append(inner, lipgloss.NewStyle().Background(surface).Width(innerW).
			Height(contentH).MaxHeight(contentH).Render(lipgloss.JoinVertical(lipgloss.Left, content...)))
	}
	if p.botSep {
		inner = append(inner, lipgloss.NewStyle().Foreground(accent).Background(surface).
			Width(innerW).Render(repeat("▁", innerW)))
	}
	body := lipgloss.JoinVertical(lipgloss.Left, inner...)
	// Clip the panel to h so it can never push the ones below it off the column.
	body = lipgloss.NewStyle().Background(surface).Width(innerW).Height(h).MaxHeight(h).Render(body)

	// Left gutter: the tall border-left cell. Color = $primary when focused.
	gutterFg := surface
	if p.region.FocusWithin() {
		gutterFg = style.Active().Color(style.Primary)
	}
	gutter := lipgloss.NewStyle().Foreground(gutterFg).Background(surface).
		Width(gutterW).Height(h).Render(repeatV("▕", h))

	return lipgloss.JoinHorizontal(lipgloss.Top, gutter, body)
}

// renderContent draws the right #content pane: the active pane rendered into the
// inner area (outer minus `padding: 1 2`) on $surface. Dispatches through the pane
// registry; unknown ids fall back to a placeholder.
func (m model) renderContent(w, h int) string {
	if w < 1 {
		w = 1
	}
	surface := style.Active().Color(style.Surface)
	text := style.Active().Color(style.Text)
	iw, ih := w-4, h-2 // inner area after padding 1 2
	if iw < 1 {
		iw = 1
	}
	if ih < 1 {
		ih = 1
	}
	var body string
	if m.contentScroll != nil {
		body = m.zm.Mark(contentScrollZoneID, m.contentScroll.Render())
	} else {
		body = m.renderPaneBody(iw, ih)
	}
	// MaxWidth/MaxHeight clip a body that still does not fit (a degenerate size,
	// e.g. a ranking header taller than the inner area), so the frame never grows
	// past the terminal.
	return lipgloss.NewStyle().
		Foreground(text).Background(surface).
		Width(w).Height(h).Padding(1, 2).
		MaxWidth(w).MaxHeight(h).
		Render(body)
}

// --- construction ---

func ptr(s string) *string { return &s }

func repeat(s string, n int) string {
	out := ""
	for i := 0; i < n; i++ {
		out += s
	}
	return out
}

func repeatV(s string, n int) string {
	out := ""
	for i := 0; i < n; i++ {
		if i > 0 {
			out += "\n"
		}
		out += s
	}
	return out
}

func bindings() []key.Binding {
	return []key.Binding{
		key.NewBinding(key.WithKeys("tab"), key.WithHelp("tab", "Focus")),
		key.NewBinding(key.WithKeys("s"), key.WithHelp("s", "Sessions")),
		key.NewBinding(key.WithKeys("c"), key.WithHelp("c", "Layouts")),
		key.NewBinding(key.WithKeys("n"), key.WithHelp("n", "New custom")),
		key.NewBinding(key.WithKeys("d"), key.WithHelp("d", "Delete custom")),
		key.NewBinding(key.WithKeys("e"), key.WithHelp("e", "Edit custom")),
		key.NewBinding(key.WithKeys("left", "right"), key.WithHelp("←/→", "Cycle")),
		key.NewBinding(key.WithKeys("[", "]"), key.WithHelp("[/]", "win/grp")),
		key.NewBinding(key.WithKeys("r"), key.WithHelp("r", "Refresh")),
		key.NewBinding(key.WithKeys("q"), key.WithHelp("q", "Quit")),
	}
}

// newModel builds the stats shell at the given size from the seeded fixture, with
// an in-memory (defaults-only, never saved) layout config. Like a harness run its
// toasts persist (no expiry tick), so a test driving every command never blocks
// on a timeout.
func newModel(cols, rows int) model {
	data := newStatsData()
	return newModelFromData(cols, rows, data, data.Sessions(), memoryStatsConfig(), app.WithPersistentToasts())
}

// newModelFromSessions builds the shell from an explicit session set (fresh seeded
// fixture) so tests can exercise both single-session and multi-session mode. Toasts
// persist, as in newModel.
func newModelFromSessions(cols, rows int, sessions []session.AitasksSession) model {
	return newModelFromData(cols, rows, newStatsData(), sessions, memoryStatsConfig(), app.WithPersistentToasts())
}

// newModelWithConfig builds the shell (seeded sessions) over a loaded layout config.
func newModelWithConfig(cols, rows int, cfg *statsConfig, rootOpts ...app.Option) model {
	data := newStatsData()
	return newModelFromData(cols, rows, data, data.Sessions(), cfg, rootOpts...)
}

// newModelFromData builds the shell from an explicit fixture + session set + config.
// rootOpts are appended to the app.Root options (e.g. app.WithPersistentToasts).
func newModelFromData(cols, rows int, data StatsData, sessions []session.AitasksSession, cfg *statsConfig, rootOpts ...app.Option) model {
	multi := len(sessions) >= 2

	// Sidebar list (the pane picker) — layout-driven: built from the resolved active
	// layout's pane ids (highlight-to-preview keys off Item.Meta = the pane id).
	sidebar := listview.New(sidebarItemsFor(cfg.resolveActiveLayout()),
		listview.WithID("sidebar"), listview.WithWidth(listW))

	// Layout list (presets, customs, "+ New custom"), cursor on the active layout.
	layout := listview.New(layoutItems(cfg), listview.WithID("layout_list"),
		listview.WithWidth(listW), listview.WithHeight(layoutListMaxRows))

	panels := make([]*panel, 0, 3)
	sessionIdx := -1

	if multi {
		sessionItems := make([]listview.Item, 0, len(sessions)+1)
		for _, s := range sessions {
			sessionItems = append(sessionItems, listview.Item{Label: sessionLabel(s.Session), Meta: s.Session})
		}
		sessionItems = append(sessionItems, listview.Item{Label: sessionLabel(allSessionsKey), Meta: allSessionsKey})
		sessionList := listview.New(sessionItems, listview.WithID("session_list"),
			listview.WithWidth(listW), listview.WithHeight(sessionListMaxRows))
		panels = append(panels, &panel{
			kind: "session", list: &sessionList, bodyID: "session_list",
			title: "Session  ← / → to cycle", botSep: true,
		})
	}
	panels = append(panels, &panel{kind: "sidebar", list: &sidebar, bodyID: "sidebar"})
	panels = append(panels, &panel{
		kind: "layout", list: &layout, bodyID: "layout_list",
		title: "Layouts", topSep: true,
	})

	// Wire each panel's list as the single member of its region.
	regions := make([]*ui.Region, len(panels))
	for i, p := range panels {
		fg := ui.NewFocusGroup()
		fg.Add(p.bodyID, p.list)
		p.region = ui.NewRegion(p.bodyID, fg)
		regions[i] = p.region
		switch p.kind {
		case "session":
			sessionIdx = i
		}
	}
	sidebarIdx, layoutIdx := -1, -1
	for i, p := range panels {
		switch p.kind {
		case "sidebar":
			sidebarIdx = i
		case "layout":
			layoutIdx = i
		}
	}

	rm := ui.NewRegionManager(regions...)

	current := sessions[0].Session
	selectedGroup := session.DefaultSelectedGroup(sessions, &current)

	m := model{
		data:          data,
		rm:            rm,
		panels:        panels,
		sessionIdx:    sessionIdx,
		sidebarIdx:    sidebarIdx,
		layoutIdx:     layoutIdx,
		sessions:      sessions,
		current:       current,
		selectedGroup: selectedGroup,
		multi:         multi,
		cols:          cols,
		rows:          rows,
		cfg:           cfg,
		sh:            &shared{},
		seedSize:      true,
	}

	// A region-based base screen: focus lives in the RegionManager and the modals
	// are opaque, so the stack needs no base blur/restore — the layout region stays
	// active underneath and is focused again on dismiss.
	m.root = app.New(append([]app.Option{
		app.WithHeader(m.titleText()),
		app.WithFooter(bindings()...),
		app.WithRegions(rm),
		app.WithModals(app.NewModalStack(app.FocusGroupScreen{FG: nil})),
	}, rootOpts...)...)
	m.zm = m.root.Zones()

	// Initial preview: the active layout's first pane (no HighlightedMsg on mount),
	// and the layout cursor on the active layout.
	m.rebuildLayoutList(cfg.Active)
	if ids := cfg.resolveActiveLayout(); len(ids) > 0 {
		m.showPane(ids[0])
	} else {
		m.showPane(noPanesID)
	}
	return m
}

// loadConfigOrDefaults loads the layered config from dir, falling back to the
// in-memory defaults (never saved) when the files are unreadable/malformed — the
// TUI must stay usable.
func loadConfigOrDefaults(dir string) *statsConfig {
	cfg, err := loadStatsConfig(filepath.Join(dir, statsConfigFile))
	if err != nil {
		fmt.Fprintln(os.Stderr, "stats: config:", err)
		return memoryStatsConfig()
	}
	return cfg
}
